// framework.ts
export class Framework {
  private hooks: (() => void)[] = [];
  register(h: () => void) { this.hooks.push(h); }
  start() { this.hooks.forEach(h => h()); }
}
// plugin.ts
framework.register(() => console.log('plugin runs when framework starts'))

class Scheduler {
  private tasks: (() => void)[] = [];
  register(task: () => void) { this.tasks.push(task); }
  runAll() { for (const t of this.tasks) t(); }
}
// usage
scheduler.register(() => emailService.sendDailyReport());

// Version A
class LoggerA {
  private handlers: ((entry: string) => void)[] = [];
  onLog(h: (entry: string) => void) { this.handlers.push(h); }
  log(msg: string) { this.handlers.forEach(h => h(msg)); }
}

// Version B
class LoggerB {
  private entries: string[] = [];
  add(msg: string) { this.entries.push(msg); }
  fetch() { return this.entries.splice(0); }
}
// Version A uses callbacks invoked by logger. Version B expects extensions to poll for entries.
